// SPDX-License-Identifier: Unlicensed
pragma solidity >=0.8.0;
contract Child {
    uint256 public x;
    constructor(uint256 _x) { x = _x; }
}
contract Other {
    uint256 public y;
    constructor() { y = 1; }
}
contract Factory {
    Child public first;
    constructor(uint256 v) { first = new Child(v); }
    function create(uint256 v) external returns (address) {
        return address(new Child(v));
    }
    function spawn() external returns (address) {
        return address(new Other());
    }
}
